package com.oldbutgold.shop.modules.commerce.application;
import com.oldbutgold.shop.modules.commerce.api.VoucherDtos.*;
import com.oldbutgold.shop.modules.commerce.application.CheckoutDtos.BuyNowRequest;
import com.oldbutgold.shop.modules.platform.application.NotificationService;
import com.oldbutgold.shop.modules.platform.infrastructure.persistence.NotificationRepository;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.Instant;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
@EnabledIfEnvironmentVariable(named="OGSHOP_VOUCHER_TEST_DB_URL",matches=".+")
class VouchersPostgresTest {
    @DynamicPropertySource static void database(DynamicPropertyRegistry p){String url=System.getenv("OGSHOP_VOUCHER_TEST_DB_URL");if(!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/ogshop_voucher_test"))throw new IllegalStateException("Dedicated voucher DB required");p.add("spring.datasource.url",()->url);p.add("spring.datasource.username",()->System.getenv("OGSHOP_TEST_DB_USER"));p.add("spring.datasource.password",()->System.getenv("OGSHOP_TEST_DB_PASSWORD"));p.add("spring.datasource.hikari.connection-init-sql",()->"SET search_path TO og_compat,public");p.add("spring.flyway.enabled",()->true);p.add("spring.jpa.hibernate.ddl-auto",()->"validate");p.add("app.vouchers.reminders-enabled",()->false);}
    @Autowired VoucherService vouchers;@Autowired CheckoutService checkout;@Autowired NotificationService notices;@Autowired VoucherReminderService reminders;@Autowired JdbcTemplate j;@Autowired PlatformTransactionManager tm;@Autowired MockMvc mvc;
    @MockitoSpyBean NotificationRepository outbox;
    @MockitoSpyBean java.time.Clock clock;
    long admin,ktv,buyer,seller,other,product,address;
    long value(String sql,Object... args){return j.queryForObject(sql,Long.class,args);}
    long user(String role){long id=value("INSERT INTO og_compat.users(email,password_hash,full_name) VALUES(?,'{noop}voucher-qa-123','Voucher QA') RETURNING user_id",UUID.randomUUID()+"@example.invalid");j.update("INSERT INTO og_compat.user_roles(user_id,role_id) SELECT ?,role_id FROM og_compat.roles WHERE role_name=?",id,role);return id;}
    @BeforeEach void setup(){reset(outbox,clock);admin=user("ADMIN");ktv=user("KTV");buyer=user("BUYER");seller=user("SELLER");other=user("BUYER");product=product();address=value("INSERT INTO og_compat.addresses(user_id,recipient_name,phone_number,province,district,ward,detail_address,is_default,ghn_province_id,ghn_district_id,ghn_ward_code) VALUES(?,'QA','0900000000','P','D','W','A',true,201,1442,'20101') RETURNING address_id",buyer);}
    @AfterEach void finish(){reset(outbox,clock);}
    long product(){return new TransactionTemplate(tm).execute(s->{long id=value("INSERT INTO og_compat.products(seller_id,category_id,title,description,listed_price,condition,status,workflow_model) VALUES(?,(SELECT min(category_id) FROM og_compat.categories),'Voucher camera','QA',100000,'GOOD','ACTIVE','LEGACY_V14') RETURNING product_id",seller);j.update("INSERT INTO og_compat.product_categories(product_id,category_id) SELECT ?,min(category_id) FROM og_compat.categories",id);return id;});}
    Save input(int quantity,boolean selfClaim){return new Save(UUID.randomUUID(),0L,"QA_"+UUID.randomUUID().toString().substring(0,8),"QA voucher","Test","ORDER_DISCOUNT","FIXED_AMOUNT",new BigDecimal("10000"),null,BigDecimal.ZERO,"CHECKOUT",List.of(),quantity,Instant.now().minusSeconds(60),Instant.now().plusSeconds(3600),true,selfClaim);}
    Campaign create(int quantity,boolean selfClaim){return vouchers.save(admin,null,input(quantity,selfClaim));}
    Claim claim(Campaign c){return new Claim(UUID.randomUUID(),c.version());}
    Bulk bulk(Campaign c,String action,String... ids){return new Bulk(UUID.randomUUID(),c.version(),action,List.of(ids),"QA reason");}
    @Test void claimsAreOwnedIdempotentAndPrivate(){Campaign c=create(10,true);Claim command=claim(c);Grant g=vouchers.claim(buyer,c.id(),command);assertThat(vouchers.claim(buyer,c.id(),command).id()).isEqualTo(g.id());assertThat(vouchers.claim(buyer,c.id(),claim(c)).id()).isEqualTo(g.id());assertThat(vouchers.wallet(buyer).grants()).extracting(Grant::id).contains(g.id());assertThat(vouchers.wallet(other).grants()).isEmpty();assertThatThrownBy(()->vouchers.wallet(ktv)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);while(notices.dispatchBatch()>0){}assertThat(notices.list(buyer,0,50).items().stream().filter(n->n.type().equals("VOUCHER_RECEIVED")).count()).isEqualTo(1);assertThat(notices.list(other,0,50).items()).isEmpty();}
    @Test void bulkFiltersPreviewRecheckAndRetry(){Campaign c=create(2,false);Bulk request=bulk(c,"GRANT",""+buyer,""+other,""+ktv);assertThat(vouchers.bulk(ktv,c.id(),request,true).successful()).isEqualTo(2);assertThat(vouchers.wallet(buyer).grants()).isEmpty();Batch result=vouchers.bulk(ktv,c.id(),request,false);assertThat(result.successful()).isEqualTo(2);assertThat(result.skipped()).isEqualTo(1);assertThat(vouchers.bulk(ktv,c.id(),request,false)).isEqualTo(result);assertThat(vouchers.targets(ktv,c.id(),"GRANT","","BUYER","ACTIVE",true,0,20).items()).isEmpty();assertThatThrownBy(()->vouchers.bulk(admin,c.id(),request,false)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);Bulk changed=new Bulk(request.commandId(),request.version(),request.action(),request.ids(),"Different");assertThatThrownBy(()->vouchers.bulk(ktv,c.id(),changed,false)).isInstanceOf(IllegalArgumentException.class);}
    @Test void onlyReceivedVoucherAppliesAndSpentVoucherNeverReturns(){Campaign c=create(10,true);assertThat(checkout.getCheckoutPreview(buyer,product,c.code()).appliedVoucher()).isNull(); assertThatThrownBy(()->checkout.buyNow(buyer,new BuyNowRequest(product,address,null,c.code()))).isInstanceOf(IllegalArgumentException.class);Grant g=vouchers.claim(buyer,c.id(),claim(c));assertThat(checkout.getCheckoutPreview(other,product,c.code()).appliedVoucher()).isNull();assertThat(checkout.getCheckoutPreview(buyer,product,c.code()).voucherDiscount()).isEqualByComparingTo("10000");var order=checkout.buyNow(buyer,new BuyNowRequest(product,address,null,c.code()));assertThat(vouchers.wallet(buyer).grants().getFirst().state()).isEqualTo("REDEEMED");assertThat(vouchers.bulk(ktv,c.id(),bulk(c,"REVOKE",g.id().toString()),false).skipped()).isEqualTo(1);assertThatThrownBy(()->j.update("UPDATE public.voucher_grants SET state='AVAILABLE' WHERE grant_id=?",g.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(j.queryForObject("SELECT wallet_grant_id FROM public.orders WHERE order_id=?",UUID.class,order.orderId())).isEqualTo(g.id());}
    @Test void revokeOnlyUnusedAndPreserveReceipt(){Campaign c=create(10,true);Grant g=vouchers.claim(buyer,c.id(),claim(c));Bulk command=bulk(c,"REVOKE",g.id().toString());assertThat(vouchers.bulk(ktv,c.id(),command,false).successful()).isEqualTo(1);assertThat(vouchers.bulk(ktv,c.id(),command,false).successful()).isEqualTo(1);assertThat(vouchers.usable(buyer,product,new BigDecimal("100000"))).isEmpty();assertThat(vouchers.bulk(ktv,c.id(),bulk(c,"REVOKE",g.id().toString()),false).skipped()).isEqualTo(1);}
    @Test void editingPolicyKeepsOwnedBenefitAndStopsNewClaims(){Campaign c=create(10,true);Grant g=vouchers.claim(buyer,c.id(),claim(c));Save s=new Save(UUID.randomUUID(),c.version(),c.code(),"Changed","New","SHIPPING_DISCOUNT","FIXED_AMOUNT",new BigDecimal("20000"),null,BigDecimal.ZERO,"CHECKOUT",List.of(),10,c.startTime(),c.endTime(),false,false);Campaign updated=vouchers.save(admin,c.id(),s);assertThat(updated.version()).isEqualTo(c.version()+1);assertThat(vouchers.resolve(buyer,c.code(),product,new BigDecimal("100000"),false).campaign().discountValue()).isEqualByComparingTo("10000");assertThat(vouchers.resolve(buyer,c.code(),product,new BigDecimal("100000"),false).campaign().voucherType()).isEqualTo("ORDER_DISCOUNT");assertThatThrownBy(()->vouchers.claim(other,c.id(),claim(updated))).isInstanceOf(IllegalArgumentException.class);assertThat(vouchers.wallet(buyer).grants().getFirst().id()).isEqualTo(g.id());}
    @Test void claimRaceRespectsLastIssuance()throws Exception{Campaign c=create(1,true);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{Callable<Boolean> a=()->{gate.await();try{vouchers.claim(buyer,c.id(),claim(c));return true;}catch(IllegalArgumentException e){return false;}};Callable<Boolean> b=()->{gate.await();try{vouchers.claim(other,c.id(),claim(c));return true;}catch(IllegalArgumentException e){return false;}};var first=pool.submit(a);var second=pool.submit(b);gate.countDown();assertThat((first.get(20,TimeUnit.SECONDS)?1:0)+(second.get(20,TimeUnit.SECONDS)?1:0)).isEqualTo(1);}finally{pool.shutdownNow();}}
    @Test void notificationFailureRollsBackWholeBatch(){Campaign c=create(10,false);doThrow(new IllegalStateException("QA outbox unavailable")).when(outbox).enqueue(anyString(),anyLong(),anyList());assertThatThrownBy(()->vouchers.bulk(ktv,c.id(),bulk(c,"GRANT",""+buyer,""+other),false)).isInstanceOf(RuntimeException.class);reset(outbox);assertThat(vouchers.wallet(buyer).grants()).isEmpty();assertThat(vouchers.wallet(other).grants()).isEmpty();}
    @Test void apiRolesAndValidationAreEnforced()throws Exception{mvc.perform(get("/api/v1/admin/vouchers").with(jwt().jwt(t->t.subject(""+buyer)).authorities(new SimpleGrantedAuthority("ROLE_BUYER")))).andExpect(status().isForbidden());mvc.perform(get("/api/v1/ktv/vouchers").with(jwt().jwt(t->t.subject(""+admin)).authorities(new SimpleGrantedAuthority("ROLE_ADMIN")))).andExpect(status().isForbidden());mvc.perform(get("/api/v1/commerce/vouchers").with(jwt().jwt(t->t.subject(""+ktv)).authorities(new SimpleGrantedAuthority("ROLE_KTV")))).andExpect(status().isForbidden());mvc.perform(post("/api/v1/admin/vouchers").contentType("application/json").content("{}").with(jwt().jwt(t->t.subject(""+admin)).authorities(new SimpleGrantedAuthority("ROLE_ADMIN")))).andExpect(status().isBadRequest());}
    @Test void remindersArePrivateAndDeduplicated(){Campaign c=create(10,true);vouchers.claim(buyer,c.id(),claim(c));reminders.scan(0);reminders.scan(0);while(notices.dispatchBatch()>0){}assertThat(notices.list(buyer,0,50).items().stream().filter(n->n.type().equals("VOUCHER_EXPIRING")).count()).isEqualTo(1);}
    @Test void previewIsRevalidatedAfterVoucherWasSpent(){Campaign c=create(10,true);Grant g=vouchers.claim(buyer,c.id(),claim(c));Bulk command=bulk(c,"REVOKE",g.id().toString());assertThat(vouchers.bulk(ktv,c.id(),command,true).successful()).isEqualTo(1);checkout.buyNow(buyer,new BuyNowRequest(product,address,null,c.code()));assertThat(vouchers.bulk(ktv,c.id(),command,false).skipped()).isEqualTo(1);}
    @Test void scopeMinimumPercentageCapAndExpiry(){Save base=input(10,true);Campaign c=vouchers.save(admin,null,new Save(base.commandId(),0L,base.code(),base.title(),base.description(),"ORDER_DISCOUNT","PERCENTAGE",new BigDecimal("50"),new BigDecimal("15000"),new BigDecimal("80000"),"PRODUCTS",List.of(product),10,base.startTime(),base.endTime(),true,true));Grant g=vouchers.claim(buyer,c.id(),claim(c));assertThat(vouchers.usable(buyer,product(),new BigDecimal("100000"))).isEmpty();assertThat(vouchers.usable(buyer,product,new BigDecimal("70000"))).isEmpty();assertThat(checkout.getCheckoutPreview(buyer,product,c.code()).voucherDiscount()).isEqualByComparingTo("15000");doReturn(c.endTime().plusSeconds(1)).when(clock).instant();assertThat(vouchers.usable(buyer,product,new BigDecimal("100000"))).isEmpty();assertThat(vouchers.bulk(ktv,c.id(),bulk(c,"REVOKE",g.id().toString()),false).skipped()).isEqualTo(1);reminders.scan(0);while(notices.dispatchBatch()>0){}assertThat(notices.list(buyer,0,50).items().stream().filter(n->n.type().equals("VOUCHER_EXPIRED")).count()).isEqualTo(1);}
    @Test void oneGrantCannotPayTwoConcurrentOrders()throws Exception{Campaign c=create(10,true);vouchers.claim(buyer,c.id(),claim(c));long second=product();ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{Callable<Boolean> a=()->{gate.await();try{checkout.buyNow(buyer,new BuyNowRequest(product,address,null,c.code()));return true;}catch(IllegalArgumentException e){return false;}};Callable<Boolean> b=()->{gate.await();try{checkout.buyNow(buyer,new BuyNowRequest(second,address,null,c.code()));return true;}catch(IllegalArgumentException e){return false;}};var first=pool.submit(a);var last=pool.submit(b);gate.countDown();assertThat((first.get(20,TimeUnit.SECONDS)?1:0)+(last.get(20,TimeUnit.SECONDS)?1:0)).isEqualTo(1);assertThat(value("SELECT count(*) FROM public.orders WHERE buyer_id=? AND wallet_grant_id IS NOT NULL",buyer)).isEqualTo(1);}finally{pool.shutdownNow();}}
    @Test void staleVersionAndOversizedBatchAreRejected(){Campaign c=create(10,false);assertThatThrownBy(()->vouchers.bulk(ktv,c.id(),new Bulk(UUID.randomUUID(),c.version()+1,"GRANT",List.of(""+buyer),"QA"),false)).isInstanceOf(IllegalArgumentException.class);var ids=java.util.stream.LongStream.range(1,102).mapToObj(Long::toString).toList();assertThatThrownBy(()->vouchers.bulk(ktv,c.id(),new Bulk(UUID.randomUUID(),c.version(),"GRANT",ids,"QA"),false)).isInstanceOf(IllegalArgumentException.class);}
}
